import { areaSections } from './task-views.js';
import type { Task } from './task-tree.js';

const leaf = (id: string, done = false): Task => ({ id, title: id, done, subtasks: [] });

describe('areaSections', () => {
  it('splits an area into direct tasks plus one flat section per group, with breadcrumbs for deeper levels', () => {
    const area: Task = {
      id: 'gun', title: 'Gun', done: false,
      subtasks: [
        leaf('recoil', true),
        { id: 'server', title: 'Server', done: false, subtasks: [leaf('logic'), { id: 'val', title: 'Validation', done: false, subtasks: [leaf('rate')] }] },
      ],
    };
    const sections = areaSections(area);
    expect(sections.map((s) => s.title)).toEqual(['General', 'Server']);
    expect(sections[1].items.map((i) => [i.task.id, i.path])).toEqual([['logic', []], ['rate', ['Validation']]]);
  });
});
